<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('expenses');$pageTitle='Expense Reports';$activeMenu='expense-reports';$from=$_GET['from']??date('Y-01-01');$to=$_GET['to']??date('Y-m-d');$dept=(int)($_GET['department_id']??0);$sql="SELECT e.*,d.name department,c.name category,CONCAT(u.first_name,' ',u.last_name) requester FROM expenses e JOIN departments d ON d.id=e.department_id JOIN budget_categories c ON c.id=e.category_id JOIN users u ON u.id=e.requested_by WHERE e.expense_date BETWEEN ? AND ?";$p=[$from,$to];if($dept){$sql.=' AND e.department_id=?';$p[]=$dept;}$sql.=' ORDER BY e.expense_date DESC';$s=db()->prepare($sql);$s->execute($p);$rows=$s->fetchAll();$total=array_sum(array_column($rows,'amount'));require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Expense Reports</h1><p>Detailed expense movement with date and department filtering.</p></div><button class="btn btn-light border no-print" onclick="window.print()"><i class="fa-solid fa-file-pdf me-2"></i>Print / PDF</button></div><div class="card-panel"><div class="card-body"><form class="row g-2 align-items-end mb-4 no-print"><div class="col-md-3"><label class="form-label">From</label><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div class="col-md-3"><label class="form-label">To</label><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div class="col-md-3"><label class="form-label">Department</label><select class="form-select" name="department_id"><option value="0">All departments</option><?php foreach(departments() as $d):?><option value="<?=$d['id']?>" <?=($dept===$d['id'])?'selected':''?>><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><button class="btn btn-primary w-100">Apply Filters</button></div></form><div class="d-flex justify-content-end mb-3"><div class="p-3 rounded-3 bg-light"><span class="text-secondary">Report Total</span><strong class="ms-3"><?=money($total)?></strong></div></div><div class="table-responsive"><table class="table data-table"><thead><tr><th>Code</th><th>Date</th><th>Department</th><th>Category</th><th>Description</th><th>Requester</th><th>Status</th><th class="text-end">Amount</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['expense_code'])?></td><td><?=e($r['expense_date'])?></td><td><?=e($r['department'])?></td><td><?=e($r['category'])?></td><td><?=e($r['description'])?></td><td><?=e($r['requester'])?></td><td><?=status_badge($r['status'])?></td><td class="text-end"><?=money($r['amount'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
